mapper.select:
SELECT id, row_version, created_at, updated_at, chapter_id, storyboard_revision_id, project_id, project_location_id, order_index, title, narration, duration_seconds, location_text, status
FROM scenes
WHERE id = #{id}

SELECT id, row_version, created_at, updated_at, scene_id, order_index, source_start, source_end, source_anchor_json::text AS source_anchor_json, purpose, summary, importance, story_functions_json::text AS story_functions_json, continuity_state_json::text AS continuity_state_json
FROM story_beats
WHERE id = #{id}

SELECT id, row_version, created_at, updated_at, story_beat_id, order_index, cue_type, speaker_project_character_id, source_start, source_end, source_anchor_json::text AS source_anchor_json, adaptation_action, adapted_text, delivery_hint, narration_text_start, narration_text_end, audio_start_ms, audio_end_ms, status
FROM audio_cues
WHERE id = #{id}

SELECT id, row_version, created_at, updated_at, scene_id, story_beat_id, order_index, title, visual_intent, beat_type, visual_summary, visual_description, visual_direction_json, review_status, motion_mode, relative_weight, visual_focus, aspect_ratio_override, preview_media_asset_id, text_start, text_end, audio_duration_ms, source_anchor_json
FROM visual_beats
WHERE id = #{id}

SELECT id, row_version, created_at, updated_at, chapter_id, storyboard_revision_id, source_hash, version, adaptation_mode, text, content_hash, status
FROM narration_scripts
WHERE id = #{id}
